import { test, expect } from '@playwright/test';

test.describe('Export Records to CSV', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/records');
  });

  test('should successfully export a list of records to CSV', async ({ page }) => {
    // Verify records table is visible
    const recordsTable = page.getByRole('table', { name: /records/i });
    await expect(recordsTable).toBeVisible();

    // Verify export button is visible and enabled
    const exportButton = page.getByRole('button', { name: /export to csv/i });
    await expect(exportButton).toBeVisible();
    await expect(exportButton).not.toBeDisabled();

    // Click export button
    await exportButton.click();

    // Wait for export confirmation message
    const successMessage = page.getByText(/export successful/i);
    await expect(successMessage).toBeVisible();

    // Verify download prompt appears
    const downloadPrompt = page.getByText(/download complete/i);
    await expect(downloadPrompt).toBeVisible();

    // Verify download link is available
    const downloadLink = page.getByRole('link', { name: /download csv/i });
    await expect(downloadLink).toBeVisible();

    // Click download link
    await downloadLink.click();

    // Verify download is initiated
    const downloadStatus = page.getByText(/downloading/i);
    await expect(downloadStatus).toBeVisible();

    // Verify download progress bar appears
    const progressBar = page.getByRole('progressbar');
    await expect(progressBar).toBeVisible();

    // Wait for download to complete
    await page.waitForTimeout(1000);

    // Verify download status updates to complete
    await expect(downloadStatus).toContainText('complete');
  });

  test('should handle empty record list export gracefully', async ({ page }) => {
    // Navigate to records page
    await page.goto('/records');

    // Verify records table is visible
    const recordsTable = page.getByRole('table', { name: /records/i });
    await expect(recordsTable).toBeVisible();

    // Verify export button is visible
    const exportButton = page.getByRole('button', { name: /export to csv/i });
    await expect(exportButton).toBeVisible();

    // Clear all records
    const clearButton = page.getByRole('button', { name: /clear all records/i });
    await clearButton.click();

    // Verify records table is empty
    const recordRows = page.locator('[data-testid="record-row"]');
    await expect(recordRows).toHaveCount(0);

    // Click export button
    await exportButton.click();

    // Verify empty export message
    const emptyExportMessage = page.getByText(/no records to export/i);
    await expect(emptyExportMessage).toBeVisible();

    // Verify no download link appears
    const downloadLink = page.getByRole('link', { name: /download csv/i });
    await expect(downloadLink).not.toBeVisible();

    // Verify error state is displayed
    const errorState = page.getByText(/export failed/i);
    await expect(errorState).not.toBeVisible();
  });
});
